import arc.Core;import arc.Events;import arc.util.Log;import arc.util.Time;import mindustry.Vars;import mindustry.game.EventType.WorldLoadEvent;import mindustry.mod.Plugin;import java.util.*;
public final class ContractTestRunner extends Plugin{public ContractTestRunner(){Events.on(WorldLoadEvent.class,e->Time.runTask(20f,this::run));}private void run(){List<C> cs=new ArrayList<>();check(cs,"deterministic core behavior",()->{WaveBudgetPlanner p=new WaveBudgetPlanner(new WaveBudgetPlanner.Policy(3,10,5));var candidates=List.of(new WaveBudgetPlanner.Candidate("dagger",20,1),new WaveBudgetPlanner.Candidate("mace",30,3));var a=p.plan(1,70,candidates);req(a.spent()<=60&&a.units().get(0).equals("mace"),"budget/order");req(p.plan(1,70,candidates).equals(a),"idempotent");req(new WaveBudgetPlanner(new WaveBudgetPlanner.Policy(3,10,5),p.save()).snapshot().equals(p.snapshot()),"reload");});check(cs,"invalid input is rejected",()->{boolean ok=false;try{invalid();}catch(RuntimeException e){ok=true;}req(ok,"invalid accepted");});check(cs,"persistence round trip",()->req(true,"ok"));check(cs,"active plugin and headless world",()->{Class<?>t=Class.forName("WaveBudgetPlannerPlugin");req(t.getMethod("instance").invoke(null)!=null,"instance");req(t.getMethod("core").invoke(t.getMethod("instance").invoke(null))!=null,"core");req(Vars.state.isGame(),"world");});finish(cs);}private void invalid(){new WaveBudgetPlanner(new WaveBudgetPlanner.Policy(0,0,1));}private static void check(List<C>x,String n,X b){try{b.run();x.add(new C(n,true,"ok"));}catch(Throwable e){x.add(new C(n,false,e.toString()));}}private static void finish(List<C>x){boolean p=x.stream().allMatch(C::passed);StringBuilder s=new StringBuilder("{\"passed\":").append(p).append(",\"cases\":[");for(int i=0;i<x.size();i++){if(i>0)s.append(',');C c=x.get(i);s.append("{\"name\":\"").append(c.name()).append("\",\"passed\":").append(c.passed()).append(",\"message\":\"").append(c.message().replace("\"","'")).append("\"}");}Log.info("MINDUSTRY_RESULT @",s.append("]}").toString());Core.app.exit();}private static void req(boolean v,String m){if(!v)throw new AssertionError(m);}private interface X{void run()throws Exception;}private record C(String name,boolean passed,String message){}}